WITH base AS (SELECT id, txn_type, amount, txn_time, merchant, is_flagged, ROUND(amount, 0) AS amount_rounded FROM transactions WHERE txn_time >= TO_TIMESTAMP('2023-09-28 13:00:00') AND merchant IS NOT NULL), flagged AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS new_group_flag FROM base), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN amount >= 4100 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, CASE WHEN session_no >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_no_tier, SUM(CASE WHEN merchant = 'Lazada' THEN amount ELSE 0 END) AS lazada_amount, COUNT_IF(txn_type = 'DEBIT') AS debit_events, MAX(txn_time) AS ended_at FROM sessionized GROUP BY amount_tier, session_no_tier HAVING COUNT_IF(txn_type = 'DEBIT') >= 1
